interface Phase { publish(doc: Document): void; }

class Draft implements Phase {
  publish(doc: Document) { doc.phase = new Published(); }
}

class Document {
  phase: Phase = new Draft();
  publish() { this.phase.publish(this); }
}

type Phase = { kind: "draft" } | { kind: "published"; version: number };

function next(phase: Phase): Phase {
  switch (phase.kind) {
    case "draft": return { kind: "published", version: 1 };
    case "published": return { kind: "published", version: phase.version + 1 };
    default: return assertNever(phase);   // compile error if a state is unhandled
  }
}
